<template><view class="account-page feature-page"><FeaturePageState :status="status" :error="error" @retry="load"/><template v-if="status==='ready'"><text class="feature-note">{{context.label}}</text><view class="business-record"><view class="business-record-title">{{data.store.name}}</view><text class="business-caption">{{data.store.address}}</text><text v-if="data.store.contact" class="business-caption">{{data.store.contact}}</text><button v-if="can('edit-store')" class="business-link" @click="editStore">编辑门店信息</button></view><view class="business-filters"><button v-for="item in tabs" :key="item.id" :class="{selected:tab===item.id}" @click="tab=item.id">{{item.label}}</button></view><template v-if="tab==='coaches'"><button v-if="can('save-coach')" class="primary" @click="editCoach(null)">添加健脑官</button><view v-for="coach in data.staff" :key="coach.id" class="business-record"><view class="business-record-title">{{coach.name}}</view><view class="business-row"><text>登录账号</text><text>{{coach.loginAccount}}</text></view><text class="business-caption">{{coach.invitationStatus==='PENDING'?'待邀请激活':'已设置登录凭证'}}</text><button v-if="can('save-coach')" class="business-link" @click="editCoach(coach)">编辑</button></view><EmptyState v-if="!data.staff.length" text="暂无健脑官"/></template><template v-else-if="tab==='owners'"><view v-for="owner in data.owners" :key="owner.id" class="business-record"><view class="business-record-title">{{owner.name}}</view><text class="business-caption">有效期：{{owner.validUntil||'—'}}</text></view><EmptyState v-if="!data.owners.length" text="暂无合店老板"/></template><template v-else-if="tab==='members'"><view v-for="member in data.members" :key="member.id" class="business-record"><view class="business-record-title">{{member.name}}</view><text class="business-caption">年级：{{member.gradeLabel||'—'}}</text><text class="business-caption">课时与消费资料以授权业务记录为准</text><text class="business-caption">{{member.remark||'暂无备注'}}</text><button class="business-link" @click="memberDetail(member.id)">查看会员</button></view><EmptyState v-if="!data.members.length" text="暂无门店会员"/></template><template v-else><view v-for="item in data.approvals" :key="item.id" class="business-record"><view class="business-record-title">{{item.title}}</view><view class="business-row"><text>{{item.applicantName}}</text><text>{{approvalStatus(item.status)}}</text></view><text v-if="item.reason" class="business-caption">{{item.reason}}</text><view v-if="item.status==='PENDING'&&can('approve')" class="business-filters"><button @click="openDecision(item,'APPROVE')">批准</button><button @click="openDecision(item,'REJECT')">拒绝</button></view></view><EmptyState v-if="!data.approvals.length" text="暂无待办申请"/></template></template><view v-if="editor" class="feature-mask" @click.self="close"><view class="feature-sheet"><view class="panel-heading">{{editor==='store'?'编辑门店':editor==='coach'?'健脑官资料':'审批确认'}}<button :disabled="saving" class="close-feature" aria-label="关闭管理表单" @click="close"><image src="/static/common/icon-close.png" mode="aspectFit"/></button></view><template v-if="editor==='store'"><view class="business-operation-field"><text>门店名称</text><input v-model="draft.name" :disabled="saving" maxlength="60"/></view><view class="business-operation-field"><text>详细地址</text><input v-model="draft.address" :disabled="saving" maxlength="200"/></view><view class="business-operation-field"><text>联系电话</text><input v-model="draft.contact" type="number" :disabled="saving" maxlength="11"/></view></template><template v-else-if="editor==='coach'"><view class="business-operation-field"><text>姓名</text><input v-model="draft.name" :disabled="saving" maxlength="24"/></view><view class="business-operation-field"><text>登录账号</text><input v-model="draft.loginAccount" :disabled="saving" maxlength="32"/></view><text class="feature-note">保存资料后，员工可通过邀请设置登录凭证。</text></template><template v-else><text class="feature-note">{{decision==='APPROVE'?'批准':'拒绝'}}：{{selectedApplication?.title}}</text><textarea v-model="draft.reason" :disabled="saving" :maxlength="200" class="store-reason" :placeholder="decision==='REJECT'?'请填写拒绝原因':'备注（选填）'"/></template><text v-if="saveError" class="business-operation-error">{{saveError}}</text><button :disabled="saving" class="primary" @click="save">{{saving?'提交中…':'确认提交'}}</button></view></view></view></template>
<script setup>
import {ref,watch,onUnmounted} from 'vue'
import {config} from '../config'
import {getBusinessContext} from '../services/business'
import {getBusinessStore,saveBusinessCoach,saveBusinessStore,decideBusinessApplication} from '../services/business-store'
import {useAsyncPage} from '../composables/useAsyncPage'
import FeaturePageState from './FeaturePageState.vue'
import EmptyState from './EmptyState.vue'
const props=defineProps({pageQuery:Object}),context=ref(null),tab=ref('coaches'),editor=ref(''),draft=ref({}),saving=ref(false),saveError=ref(''),selectedApplication=ref(null),decision=ref(''),isMock=config.useMock,tabs=[{id:'coaches',label:'健脑官'},{id:'owners',label:'合店老板'},{id:'members',label:'门店会员'},{id:'approvals',label:'待办审批'}]
let active=true,attemptKey='',attemptPayload=''
const {data,status,error,load}=useAsyncPage(async()=>{const ctx=await getBusinessContext('agency',props.pageQuery?.contextId);context.value=ctx;return getBusinessStore(ctx.id)},false)
watch(()=>props.pageQuery,query=>{if(query)load()},{immediate:true})
const can=action=>data.value?.allowedActions?.includes(action)
const approvalStatus=status=>({PENDING:'待审核',APPROVED:'已通过',REJECTED:'已拒绝'}[status]||'状态待确认')
function memberDetail(id){uni.navigateTo({url:`/pages/members/detail?contextId=${encodeURIComponent(context.value.id)}&memberId=${encodeURIComponent(id)}`})}
function reset(){saveError.value='';attemptKey='';attemptPayload=''}
function editStore(){reset();editor.value='store';draft.value={...data.value.store}}
function editCoach(coach){reset();editor.value='coach';draft.value={id:coach?.id||'',name:coach?.name||'',loginAccount:coach?.loginAccount||'',version:coach?.version}}
function openDecision(item,value){reset();editor.value='decision';selectedApplication.value=item;decision.value=value;draft.value={reason:''}}
function close(){if(!saving.value)editor.value=''}
async function save(){if(saving.value)return;saving.value=true;saveError.value='';const mode=editor.value;const fingerprint=JSON.stringify({mode,draft:draft.value,application:selectedApplication.value?.id,decision:decision.value});if(fingerprint!==attemptPayload){attemptPayload=fingerprint;attemptKey=`store-${Date.now()}-${Math.random().toString(36).slice(2)}`}try{let result;if(mode==='store')result=await saveBusinessStore(context.value.id,data.value.store.id,draft.value);else if(mode==='coach')result=await saveBusinessCoach(context.value.id,data.value.store.id,draft.value.id,draft.value,attemptKey);else result=await decideBusinessApplication(context.value.id,data.value.store.id,selectedApplication.value.id,{decision:decision.value,reason:draft.value.reason,version:selectedApplication.value.version,idempotencyKey:attemptKey});if(!active)return;editor.value='';if(mode==='decision')uni.showModal({title:'审核已记录',content:result.nextStep||'请等待后续处理，审批不代表已经开通。',showCancel:false});else uni.showToast({title:'已保存',icon:'success'});await load()}catch(reason){if(active)saveError.value=reason.message||'提交失败'}finally{if(active)saving.value=false}}
onUnmounted(()=>{active=false});defineExpose({refresh:()=>{if(!editor.value)return load()}})
</script>
<style>@import '../styles/account.css';@import '../styles/exclusive.css';@import '../styles/business.css';</style>
<style scoped>.store-reason{background:#454f70;border-radius:1em;width:100%;min-height:8em;padding:1em;color:white;font-size:1em;line-height:1.8}.business-operation-field input{color:white}</style>
